-- applied 2026-10-18 to project naihzzlszvrkxrxogsuz
-- Issue 1: one payslip per staff member + draft payslip deletion.
-- Full statements are recorded in the commit body below.
--   1. payroll_audit_event_check extended with 'payslip_deleted'
--   2. duplicate active payroll_staff rows collapsed (is_active = false; history kept)
--   3. UNIQUE INDEX payroll_staff_active_identity_uidx
--   4. trigger payroll_staff_identity_guard + payroll_guard_staff_identity()
--   5. payroll_delete_line(uuid) - draft-only, audited, bumps run revision
--   6. payroll_build_draft: null p_expected_revision now rebuilds instead of raising

CREATE OR REPLACE FUNCTION public.payroll_build_draft(p_month date, p_expected_revision integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$ DECLARE s uuid; r public.payroll_runs; staff public.payroll_staff; comp jsonb; calc jsonb; existed boolean; old_lines jsonb; BEGIN s := public.payroll_require_school_admin(); IF p_month IS NULL OR extract(day FROM p_month) <> 1 OR p_month NOT BETWEEN DATE '2000-01-01' AND DATE '2100-12-01' THEN RAISE EXCEPTION 'Choose a valid first-of-month date'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('payroll:' || s::text,0)); SELECT * INTO r FROM public.payroll_runs WHERE school_id = s AND payroll_month = p_month FOR UPDATE; existed := FOUND; IF existed THEN IF r.status <> 'draft' THEN RAISE EXCEPTION 'A confirmed/reversed run already occupies this month; its evidence cannot be overwritten'; END IF; IF p_expected_revision IS NOT NULL AND p_expected_revision IS DISTINCT FROM r.revision THEN RAISE EXCEPTION 'Draft changed. Reload and review before rebuilding.'; END IF; SELECT coalesce(jsonb_agg(to_jsonb(l) - ARRAY['bank_name','bank_account_last4'] ORDER BY l.staff_id),'[]'::jsonb) INTO old_lines FROM public.payroll_lines l WHERE l.run_id = r.id AND l.school_id = s; DELETE FROM public.payroll_lines WHERE run_id = r.id AND school_id = s; UPDATE public.payroll_runs SET revision = revision + 1, school_name = x.name, school_address = x.address, school_logo_url = x.logo_url FROM public.schools x WHERE public.payroll_runs.id = r.id AND x.id = s RETURNING public.payroll_runs.* INTO r; ELSE INSERT INTO public.payroll_runs(school_id,payroll_month,school_name,school_address,school_logo_url,created_by) SELECT s,p_month,name,address,logo_url,auth.uid() FROM public.schools WHERE id = s RETURNING * INTO r; IF NOT FOUND THEN RAISE EXCEPTION 'School not found'; END IF; END IF; FOR staff IN SELECT * FROM public.payroll_staff WHERE school_id = s AND is_active ORDER BY id LOOP SELECT coalesce(jsonb_agg(jsonb_build_object('name',name,'kind',kind,'amount',amount,'is_percentage',is_percentage,'percentage_of',percentage_of,'is_statutory',is_statutory) ORDER BY name,id),'[]'::jsonb) INTO comp FROM public.payroll_staff_components WHERE staff_id = staff.id AND school_id = s; calc := public.payroll_calculate_snapshot(staff.basic_salary,comp); INSERT INTO public.payroll_lines(school_id,run_id,staff_id,staff_name,staff_number,bank_name,bank_account_last4,position,department,basic_salary,component_snapshot,earnings,deductions,gross_pay,total_deductions,statutory_deductions,net_pay) VALUES(s,r.id,staff.id,staff.full_name,staff.staff_number,staff.bank_name,right(staff.bank_account,4),staff.position,staff.department,staff.basic_salary,comp,calc->'earnings',calc->'deductions', (calc->>'gross_pay')::numeric,(calc->>'total_deductions')::numeric,(calc->>'statutory_deductions')::numeric,(calc->>'net_pay')::numeric); END LOOP; UPDATE public.payroll_lines l SET opening_arrears = coalesce((SELECT sum(x.arrears) FROM public.payroll_lines x JOIN public.payroll_runs q ON q.id = x.run_id AND q.school_id = x.school_id WHERE x.school_id = s AND x.staff_id = l.staff_id AND q.status = 'confirmed' AND q.payroll_month < p_month),0) WHERE l.run_id = r.id; IF NOT EXISTS (SELECT 1 FROM public.payroll_lines WHERE run_id = r.id) THEN RAISE EXCEPTION 'Add at least one active staff member first'; END IF; INSERT INTO public.payroll_audit(school_id,run_id,actor_id,event,detail) VALUES(s,r.id,auth.uid(),CASE WHEN existed THEN 'draft_rebuilt' ELSE 'draft_created' END, jsonb_build_object('revision',r.revision,'replaced_lines',old_lines,'one_off_adjustments_reset',existed,'payroll_month',p_month)); RETURN r.id; END $function$;
